ee:message.ee:set-payload:
%dw 2.0
output application/xml
ns add urn:messages_2021_1.platform.webservices.netsuite.com
ns tranSales urn:sales_2021_1.transactions.webservices.netsuite.com
ns ns02 urn:core.platform.webservices.netsuite.com
ns xsi http://www.w3.org/2001/XMLSchema-instance

var invoices = vars.excelData.Sheet1
---
add#upsertList: {
    add#record: invoices map (invoice) -> {
        '@xsi:type': "tranSales:Invoice",
        '@externalId': invoice.externalId,
        tranSales#entity @(internalId: invoice.entity_internalId): null,
        tranSales#memo: invoice.memo,
        tranSales#customForm @(internalId: invoice.customForm_internalId): null,
        tranSales#department @(internalId: invoice.department_internalId): null,
        tranSales#account @(internalId: invoice.account_internalId): "International Trip Registration",
        tranSales#currency @(internalId: invoice.currency_internalId): null,
        tranSales#exchangeRate: invoice.exchangeRate,
        tranSales#tranDate: invoice.tranDate,
        tranSales#customFieldList: {
            ns02#customField @('xsi:type': "ns02:StringCustomFieldRef", scriptId: "custbodyinvoice_id"): {
                ns02#value: invoice.custbodyinvoice_id
            }
        },
        tranSales#postingPeriod @(internalId: invoice.postingPeriod_internalId): null,
        tranSales#itemList: {
            tranSales#item: {
                tranSales#item @(internalId: invoice.item_internalId): null,
                tranSales#quantity: invoice.quantity,
                tranSales#description: invoice.description,
                tranSales#location @(internalId: invoice.location_internalId): null,
                tranSales#amount: invoice.amount,
                tranSales#customFieldList: {
                    ns02#customField @('xsi:type': "ns02:StringCustomFieldRef", scriptId: "custcol1"): {
                        ns02#value: invoice.custcol1
                    },
                    ns02#customField @('xsi:type': "ns02:StringCustomFieldRef", scriptId: "custcol2"): {
                        ns02#value: invoice.custcol2
                    }
                }
            }
        }
    }
}
